import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Computational Language Authoring","description":"","frontmatter":{"title":"Computational Language Authoring","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed\\n\\nDepends on [ADR-0063 — Scheme-Core Completeness](./0063-scheme-core-completeness.md)\\n(the core must be able to describe handl before handl is used to author\\nlanguages). Refines [ADR-0044 — Language as Data and Runtime\\nSplit](./0044-language-as-data-and-runtime-split.md) Phase 8 and\\n[ADR-0041 — Languages as First-Class Values](./0041-languages-as-first-class-values.md)\\n§4 (language combinators as handl functions)."},"headers":[],"relativePath":"handl/project/adrs/0064-computational-language-authoring.md","filePath":"vendored/handl/project/adrs/0064-computational-language-authoring.md"}`),a={name:`handl/project/adrs/0064-computational-language-authoring.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0064-computational-language-authoring" tabindex="-1">ADR-0064: Computational Language Authoring <a class="header-anchor" href="#adr-0064-computational-language-authoring" aria-label="Permalink to “ADR-0064: Computational Language Authoring”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-fragment-constructors-as-handl-functions" tabindex="-1">1. Fragment constructors as handl functions <a class="header-anchor" href="#_1-fragment-constructors-as-handl-functions" aria-label="Permalink to “1. Fragment constructors as handl functions”">​</a></h3><p>Expose the fragment types (<code>TokenKindDef</code>, <code>GrammarRow</code>, <code>EvalSchemeDef</code>, <code>AstShapeDef</code>, <code>CapabilityDecl</code>, <code>OptionSchema</code>) as handl-callable constructors. A handl program builds fragments by calling functions, not by writing YAML:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># Instead of YAML:</span></span>
<span class="line"><span>#   - id: plus</span></span>
<span class="line"><span>#     position: infix</span></span>
<span class="line"><span>#     lbp: 20</span></span>
<span class="line"><span>#     rbp: 20</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Computational:</span></span>
<span class="line"><span>binary-op = fn(name, lbp, rbp) {</span></span>
<span class="line"><span>  grammar-row {</span></span>
<span class="line"><span>    id: name,</span></span>
<span class="line"><span>    position: &quot;infix&quot;,</span></span>
<span class="line"><span>    lbp: lbp,</span></span>
<span class="line"><span>    rbp: rbp,</span></span>
<span class="line"><span>    shape: [&quot;expr&quot;, &quot;expr&quot;],</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>plus  = binary-op(&quot;plus&quot;,  20, 20);</span></span>
<span class="line"><span>minus = binary-op(&quot;minus&quot;, 20, 20);</span></span>
<span class="line"><span>star  = binary-op(&quot;star&quot;,  40, 40);</span></span></code></pre></div><p>The <code>binary-op</code> function abstracts over a repetitive pattern. YAML cannot do this. This is the value.</p><h3 id="_2-fragment-set-combinators-as-handl-functions" tabindex="-1">2. Fragment-set combinators as handl functions <a class="header-anchor" href="#_2-fragment-set-combinators-as-handl-functions" aria-label="Permalink to “2. Fragment-set combinators as handl functions”">​</a></h3><p><code>Language::merge</code> (ADR-0044 §1) is exposed as a handl function. Fragment sets are built by composition:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>arith-ops = fragment-set([plus, minus, star, slash]);</span></span>
<span class="line"><span>compare-ops = fragment-set([eq, neq, lt, gt]);</span></span>
<span class="line"><span>all-ops = merge(arith-ops, compare-ops);</span></span></code></pre></div><p><code>extend</code>/<code>merge</code>/<code>restrict</code> (ADR-0041 §4) are handl functions over fragment sets, not host-side registry mutations. The result is a <code>Language</code> value — data, not a side effect.</p><h3 id="_3-parameterized-language-templates" tabindex="-1">3. Parameterized language templates <a class="header-anchor" href="#_3-parameterized-language-templates" aria-label="Permalink to “3. Parameterized language templates”">​</a></h3><p>A handl function can produce a <code>Language</code> parameterized by inputs:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>make-arith-lang = fn(ops, builtins) {</span></span>
<span class="line"><span>  language {</span></span>
<span class="line"><span>    tokens:  arith-tokens(ops),</span></span>
<span class="line"><span>    grammar: arith-grammar(ops),</span></span>
<span class="line"><span>    eval:    arith-eval(ops, builtins),</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>calc-lang = make-arith-lang([plus, minus, star], [sin, cos, sqrt]);</span></span></code></pre></div><p>This is the abstraction YAML cannot provide. A family of related languages (arith calculator, scientific calculator, matrix calculator) shares one parameterized definition.</p><h3 id="_4-the-authored-language-is-still-data" tabindex="-1">4. The authored <code>Language</code> is still data <a class="header-anchor" href="#_4-the-authored-language-is-still-data" aria-label="Permalink to “4. The authored Language is still data”">​</a></h3><p>The output of a handl authoring program is a <code>Language</code> value — the same serde-serializable data structure ADR-0044 defines. It can be serialized, cached (ADR-0065), chunked (ADR-0066), and certified (ADR-0067). The authoring path is a <em>build step</em> that produces data; the runtime consumes the data, not the authoring program.</p><p>This preserves ADR-0044&#39;s core property: <code>Language</code> is data, no Rust, no closures, no host-specific state. The authoring handl program runs at build time (or load time, with caching); the resulting <code>Language</code> is pure data at eval time.</p><h3 id="_5-yaml-remains-a-valid-authoring-path" tabindex="-1">5. YAML remains a valid authoring path <a class="header-anchor" href="#_5-yaml-remains-a-valid-authoring-path" aria-label="Permalink to “5. YAML remains a valid authoring path”">​</a></h3><p>YAML is not deprecated. It remains the simplest path for static, hand-written language definitions. Computational authoring is an <em>additional</em> path for languages that benefit from abstraction and parameterization. The two paths produce the same <code>Language</code> data structure and can be mixed: a YAML base with computationally generated extensions.</p><h3 id="_6-the-bootstrap-is-computational-authoring-of-handl-itself" tabindex="-1">6. The bootstrap is computational authoring of handl itself <a class="header-anchor" href="#_6-the-bootstrap-is-computational-authoring-of-handl-itself" aria-label="Permalink to “6. The bootstrap is computational authoring of handl itself”">​</a></h3><p>ADR-0044 Phase 8&#39;s <code>handl-defining-handl</code> is the canonical use case: a handl program that computes the <code>Language</code> value describing handl. With computational authoring, this is not a 5,000-line YAML file — it is a handl program that uses <code>binary-op</code>, <code>statement-form</code>, <code>desugar-rule</code> constructors to build the language with shared abstractions. The self-hosting bootstrap becomes a build step that runs the authoring program and serializes the result.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0044 made <code>Language</code> pure data: 7 YAML files, serde-serializable, embedded at compile time. This is declarative — but YAML is <em>literally</em> declarative. Transcribing the same literals into handl syntax gains nothing; the data is identical, the expressiveness is identical.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Abstraction over repetitive language structure.</strong> The <code>binary-op</code></li><li><strong>Parameterized language families.</strong> Related languages share a definition;</li><li><strong>The self-hosting bootstrap is a program, not a data file.</strong> handl defines</li><li><strong>The output is still data.</strong> No runtime dependency on the authoring</li><li><strong>Two authoring paths.</strong> YAML and handl programs coexist. The framework</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0064-computational-language-authoring.html"><code>design/0064-computational-language-authoring.md</code></a>.</p>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};